import {floodEvidenceHTML} from './flood-ui.js';
import {withTimeout} from './request-timeout.js';
import {hazardDesk} from './hazard-ui.js';
import {ServerClock,cacheDeadline,evidenceStatus} from './time-status.js';
import {detailedForecastHTML,forecastChart,forecastCSV} from './forecast-ui.js';
import {LiveAtlas} from './live-map.js';
import {FreeSummarizer,evidenceFacts} from './free-ai.js';
import {writeHistory,readHistory} from '/evidence-cache.js';
const $ = (s, root = document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (n, digits = 1) => typeof n === 'number' && Number.isFinite(n) ? new Intl.NumberFormat('en-PK', {maximumFractionDigits: digits}).format(n) : '—';
const time = d => d && Number.isFinite(Date.parse(d)) ? new Intl.DateTimeFormat('en-PK', {timeZone:'Asia/Karachi',hour:'2-digit',minute:'2-digit',day:'2-digit',month:'short',year:'numeric'}).format(new Date(d)) + ' PKT' : 'Upstream time not supplied';
const safeUrl = url => { try { return new URL(url).protocol === 'https:' ? esc(url) : '#'; } catch { return '#'; } };
class EvidenceClient {
  cache = new Map();
  async get(path, force = false) {
    const cached = this.cache.get(path); if (!force && cached && realNow() < cached.expires) return cached.value;
    return withTimeout(65000, async signal => {
    let response;try{response=await fetch('/api/public/v1/' + path,{signal});}catch(error){if(state.view==='widget'||path==='locations'){const history=readHistory(localStorage,path,realNow());if(history)return history;}throw error;}
    if(!response.ok){if(state.view==='widget'||path==='locations'){const history=readHistory(localStorage,path,realNow());if(history)return history;}throw new Error(`Evidence request failed (HTTP ${response.status})`);}
    const value = await response.json(); writeHistory(localStorage,path,value,realNow()); this.cache.set(path,{expires:cacheDeadline(realNow()),value}); return value;
    });
  }
  async officer(message, location, onEvent=()=>{}) { return withTimeout(65000, async signal => { const r=await fetch('/api/officer',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/x-ndjson'},body:JSON.stringify({message,location}),signal});if(!r.ok){const value=await r.json();throw new Error(`HTTP ${r.status} · ${value.message??value.error??'Evidence briefing request failed'}`);}const reader=r.body.getReader(),decoder=new TextDecoder();let pending='',brief;while(true){const {done,value}=await reader.read();pending+=decoder.decode(value??new Uint8Array(),{stream:!done});let index;while((index=pending.indexOf('\n'))>=0){const line=pending.slice(0,index);pending=pending.slice(index+1);if(!line)continue;const event=JSON.parse(line);if(event.type==='error')throw new Error(event.message);if(event.type==='complete')brief=event.brief;else onEvent(event);}if(done)break;}if(!brief)throw new Error('Evidence stream ended before a complete briefing arrived.');return brief; }); }
}
const client = new EvidenceClient();
const serverClock=new ServerClock();
const realNow=()=>serverClock.now()??Date.now();
let renderEpoch=0;
let refreshing=false;
const state = {locations:[],overview:null,selected:'karachi',snapshot:null,forecast:null,sources:null,view:'overview',briefKind:'national',point:null,satellite:null,layer:'context',zoom:5,query:''};
const descriptions = {
 alerts:['Know what is changing.<br><em>Stay a step ahead.</em>','Your district forecast and official publications, alongside seismic and satellite reports.<br class="desktop-br"> Source times, coverage and update status stay in view.'],
 forecast:['Every hour, in focus.<br><em>Plan with the full picture.</em>','A seven-day point outlook for every registered district. Inspect rainfall, wind, humidity,<br class="desktop-br"> and feels-like temperature, with an evidence receipt for every report.'],
 overview:['Follow the water.<br><em>See the evidence.</em>','Climate intelligence, grounded in evidence. Monitor changing conditions,<br class="desktop-br"> understand the context, and see exactly what we know.'],
 map:['Pakistan, in view.<br><em>Satellite to street.</em>','NASA flood composites, VIIRS satellite imagery, and past radar. Drag, zoom,<br class="desktop-br"> and click any coordinate in Pakistan to inspect the latest model data.'],
 dashboard:['Signals, in perspective.<br><em>Evidence you can inspect.</em>','Compare model forecasts across reference locations. Each reading retains<br class="desktop-br"> its units, source, retrieval time, and limitations.'],
 officer:['Ask with confidence.<br><em>Answers with evidence.</em>','A structured evidence officer for operational questions. Free local AI selects the most relevant verified facts.<br class="desktop-br"> Every displayed measurement stays tied to its original evidence.'],
 briefings:['The situation, distilled.<br><em>A brief built on evidence.</em>','Traceable operational context for four audiences. Every briefing makes<br class="desktop-br"> unavailable inputs and unverified impacts explicit.'],
 watch:['Your places. Your perspective.<br><em>Stay close to what matters.</em>','Search 160 published districts and keep places in a private browser watchlist.<br class="desktop-br"> No account is required; preferences stay on this device.'],
 sources:['Trust is traceable.<br><em>Follow every signal to its source.</em>','An open evidence ledger: source identity, methodology, freshness,<br class="desktop-br"> licensing, and the precise reason when a feed is unavailable.'],
 ops:['A transparent system.<br><em>No silent failures.</em>','Inspect source availability, request latency and circuit state.<br class="desktop-br"> Failed connectors never produce replacement measurements.'],
 methodology:['Know the limits.<br><em>Understand the evidence.</em>','Scientific integrity is a system requirement, from a source response<br class="desktop-br"> to the number you see on screen.']
};
function toast(text){const el=$('#toast');el.textContent=text;el.hidden=false;setTimeout(()=>el.hidden=true,4500);}
function badge(envelope){const status=evidenceStatus(envelope,serverClock.now());return `<span class="badge ${['AVAILABLE','FORECAST','REPORT'].includes(status)?'available':''}">${esc(status)}</span>`;}
function historyNotice(value){return value?._historical?`<div class="history-banner" role="status"><strong>CACHED (${value._historical.age_minutes} min ago)</strong><span>Historical evidence · not current conditions. Stored ${esc(time(value._historical.stored_at))}.</span></div>`:'';}
function provenance(envelope){if(!envelope)return '';return `<details class="metric-evidence"><summary>Inspect source & time</summary><div>${badge(envelope)}<br>${esc(envelope.source.name)} · Tier ${envelope.source.tier}<br>${esc(envelope.source.temporal_kind)} · ${envelope.source.latency_ms} ms<br>Valid: ${esc(time(envelope.source.updated_at))}<br>Retrieved: ${esc(time(envelope.source.retrieved_at))}<br>${!envelope.ok?esc(envelope.error.code+' · '+envelope.error.message):''}<a href="/sources/${esc(envelope.source.id)}">Full source record ↗</a></div></details>`;}
function metric(label,value,unit,envelope){return `<div><div class="metric-label">${label}</div><div class="metric-value">${fmt(value)} <small>${unit}</small></div>${provenance(envelope)}</div>`;}
function selector(){return `<input type="search" id="place-search" placeholder="Search 160 districts…" aria-label="Filter district names" autocomplete="off"><select id="location-select" aria-label="Monitoring location">${state.locations.map(l=>`<option value="${esc(l.slug)}" ${l.slug===state.selected?'selected':''}>${esc(l.name)} · ${esc(l.province)}</option>`).join('')}</select>`;}
function stat(label,value,unit,sub,symbol){return `<div class="stat"><div class="stat-label">${label}<span>${symbol}</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-sub">${sub}</div></div>`;}
function nationalStats(){const rows=state.overview?.locations??[];const available=rows.filter(s=>s.weather.ok).length;const forecast=rows.filter(s=>s.weather.ok).map(s=>s.weather.data.rain_next_24h_mm);const max=forecast.length?Math.max(...forecast):null;return `<div class="stat-grid">${stat('District registry','160','published districts','<span class="dot"></span> OCHA/WFP · valid September 2022','⌖')}${stat('Weather availability',`${rows.length?available:'—'}<small>/ ${rows.length||12}</small>`,'feeds',`${rows.length?'Latest retrieval completed':'Awaiting evidence'} · not a confidence score`,'⌁')}${stat('Highest 24h rainfall',fmt(max),'mm · forecast','Among available reference points only','☂')}${stat('Hazard assessment','—','unassessed','<span class="dot offline"></span> Independent evidence incomplete','◇')}</div>`;}
let atlas, atlasView, pointEpoch=0;
const freeAI=new FreeSummarizer();
function mapHTML(full=false){return `<div class="live-map-shell"><div class="layer-toolbar"><label><input type="checkbox" data-map-toggle="flood" checked> NASA flood</label><label><input type="checkbox" data-map-toggle="truecolor"> Satellite</label><label><input type="checkbox" data-map-toggle="radar"> Radar</label><button class="button" data-map-reset>⌖ Pakistan</button></div><div class="atlas ${full?'full':''}" id="atlas" aria-label="Interactive flood intelligence map"></div><div class="imagery-controls"><label>Flood imagery date <input type="date" data-satellite-date aria-label="NASA imagery date"></label><label>Opacity <input type="range" min="0.1" max="1" step="0.05" value="0.75" data-map-opacity aria-label="Imagery opacity"></label></div><div class="radar-controls"><button class="button" data-play-radar>▶ Play</button><input type="range" min="0" max="0" value="0" data-radar-frame aria-label="Past radar frame"><span data-radar-time>Past radar · waiting for catalog</span></div><div class="map-evidence-status" data-layer-status>Loading the interactive atlas…</div><div class="flood-legend"><span><i style="background:#32d2f5"></i>Surface water</span><span><i style="background:#ffff00"></i>Recurring flood</span><span><i style="background:#fa1e24"></i>Detected flood</span><span><i style="background:#afafaf"></i>Insufficient data</span></div><div class="query-description">NASA MODIS 3-day composite. Clouds, shadows, or missing pixels can obscure floodwater. A clear or empty tile does not establish safety. Click the map for a coordinate check.</div></div>`;}
function disposeMap(){if(atlas){atlasView=atlas.getView();atlas.destroy();atlas=null;}}
function observeMap(){disposeMap();const element=$('#atlas');if(element){atlas=new LiveAtlas({element,locations:state.locations,client,onPoint:inspectPoint,onLocation:selectLocation,view:atlasView});atlas.start();}}
async function inspectPoint(lat,lon){const epoch=++pointEpoch;toast('Checking the selected coordinate…');try{const result=await client.get(`snapshot?lat=${lat.toFixed(4)}&lon=${lon.toFixed(4)}`);if(epoch!==pointEpoch)return;state.snapshot=result;state.point={lat:result.location.lat,lon:result.location.lon};updatePointPanels();}catch(e){toast(e.message);}}
function updatePointPanels(){state.satellite=null;const panel=$('.location-panel');if(panel){panel.outerHTML=locationPanel();bindLocationActions();}const receipt=$('#snapshot-sources');if(receipt)receipt.innerHTML=sourceRows();const link=$('#selected-forecast');if(link)link.href='/forecast?location='+encodeURIComponent(state.selected);const outlook=$('#flood-outlook');if(outlook)outlook.outerHTML=floodOutlook();loadSatellitePoint();}
function selectedSnapshotPath(){return state.point?`snapshot?lat=${state.point.lat}&lon=${state.point.lon}`:'districts/'+state.selected;}
function floodOutlook(){return floodEvidenceHTML(state.snapshot,{esc,fmt,time,provenance});}
function satelliteStatus(){const e=state.satellite;const names={DETECTED_FLOOD:'NASA pixel: detected flood',RECURRING_FLOOD:'NASA pixel: recurring flood',SURFACE_WATER:'NASA pixel: surface water',INSUFFICIENT_DATA:'NASA pixel: insufficient data',NO_VISIBLE_CLASSIFICATION:'NASA pixel: no visible classification',UNRECOGNISED_CLASSIFICATION:'NASA pixel: unrecognised colour'};return `<div class="satellite-point" id="satellite-point"><span class="eyebrow">SATELLITE FLOOD CHECK</span><strong>${e?e.ok?esc(names[e.data.classification]??'Classification unavailable'):'Satellite check unavailable':'Checking NASA MODIS pixel…'}</strong><small>${e?e.ok?`3-day composite · ${esc(e.data.date)} UTC. Visualization pixel, not a ground confirmation.`:esc(e.error.code)+' · '+esc(e.error.message):'No API key required · NASA GIBS'}</small><p>Clouds, shadows and transparent pixels can hide water. An empty pixel never establishes safety.</p></div>`;}
async function loadSatellitePoint(){const s=state.snapshot;if(!s||!$('#satellite-point'))return;const identity=`${s.location.lat},${s.location.lon}`;try{const e=await client.get(`flood-observation?lat=${s.location.lat}&lon=${s.location.lon}`);if(`${state.snapshot?.location.lat},${state.snapshot?.location.lon}`!==identity)return;state.satellite=e;const el=$('#satellite-point');if(el)el.outerHTML=satelliteStatus();}catch(error){const el=$('#satellite-point');if(el)el.textContent='Satellite check unavailable: '+error.message;}}
function snapshotAvailability(s){if(!s)return '';const es=[s.weather,s.flood,s.air,s.elevation],n=es.filter(e=>e?.ok).length;return `<div class="evidence-note" role="status"><strong>${n}/4 core feeds returned data.</strong> Flood risk needs validated local thresholds and terrain/drainage evidence. Available readings below are separate from a flood warning. <a href="/alerts">Read official advisories ↗</a></div>`;}
function locationPanel(){const s=state.snapshot;const l=s?.location??state.locations.find(l=>l.slug===state.selected);const w=s?.weather;return `${historyNotice(s)}<div class="panel location-panel"><div class="section-divider">LOCATION SNAPSHOT</div><div class="location-heading"><div><h2>${esc(l?.name??'Karachi')}</h2><small>${esc(l?.province??'Sindh')} · ${esc(l?.profile??'Urban & coastal')}</small></div><span class="badge" title="Flood hazard has no validated local calibration">FLOOD RISK NOT ASSESSED</span></div>${snapshotAvailability(s)}<div class="metrics">${metric('24h rainfall · forecast',w?.ok?w.data.rain_next_24h_mm:null,'mm',w)}${metric('Temperature · forecast',w?.ok?w.data.temp_c:null,'°C',w)}${metric('River discharge · model',s?.flood.ok?s.flood.data.discharge_cms:null,'m³/s',s?.flood)}${metric('PM2.5 · model',s?.air.ok?s.air.data.pm25:null,'µg/m³',s?.air)}</div><div class="evidence-note">${w? w.ok?`Forecast valid ${time(w.source.updated_at)}. Retrieved ${time(w.source.retrieved_at)}.`:`DATA SOURCE OFFLINE · ${esc(w.error.code)}. ${esc(w.error.message)}`:'Fetching source-backed readings…'}</div>${state.view!=='widget'?satelliteStatus():''}<div class="location-select">${state.point?'<span class="coordinates">Selected map point</span>':''}${selector()}<button class="button" id="save-place" aria-label="Save selected place">⌖</button></div></div>`;}
function sourceRows(){const s=state.snapshot;if(!s)return '<div class="empty-state">Source evidence is being retrieved.</div>';return [s.weather,s.flood,s.air,s.elevation].map((e,i)=>`<a class="list-row" href="/sources/${esc(e.source.id)}"><span class="source-symbol">${['W','R','A','E'][i]}</span><div><h3>${esc(e.source.name)}</h3><small>${e.ok?`${e.source.latency_ms} ms · ${e.source.temporal_kind.toUpperCase()} · ${e.cached?'cached':'retrieved'} ${time(e.source.retrieved_at)}`:`${esc(e.error.code)} · ${esc(e.error.message)}`}</small></div>${badge(e)}</a>`).join('');}
function overviewView(){return `${nationalStats()}<div class="forecast-entry"><div><span class="eyebrow">DETAILED DISTRICT FORECAST</span><p>Seven days. Every hour. Rainfall, humidity, wind and feels-like temperature, with exportable evidence.</p></div><a class="button primary" id="selected-forecast" href="/forecast?location=${esc(state.selected)}">Open forecast workspace ↗</a></div><div class="main-grid"><section class="panel"><div class="panel-header"><div class="panel-title"><span>◎</span>National situation atlas</div><span class="badge available">AUTO REFRESH · 5 MIN</span></div>${mapHTML()}<div class="map-footer"><span>23.5°–37.5° N / 60.5°–78.0° E</span><a href="/map">Explore full atlas ↗</a></div></section><div class="right-stack">${locationPanel()}<div class="panel brief-card"><div class="eyebrow">▤ &nbsp; THE EVIDENCE BRIEF</div><h3>Preparation begins<br>with a clearer picture.</h3><p>Review a structured briefing with exact units, source timestamps, and an explicit audit of missing evidence.</p><a href="/briefings">Read the latest briefing <span style="float:right">↗</span></a></div></div></div><div class="lower-grid"><section class="panel"><div class="panel-header"><div class="panel-title"><span>⌁</span>Source pulse</div><a href="/sources">Inspect evidence ↗</a></div><div id="snapshot-sources">${sourceRows()}</div></section>${floodOutlook()}</div>`;}
function chart(s){if(!s?.weather.ok)return `<div class="empty-state"><strong>DATA SOURCE OFFLINE</strong>${esc(s?.weather.error.message??'Forecast pending')}. No chart has been generated.</div>`;const hours=s.weather.data.hours.slice(0,24);const max=Math.max(1,...hours.map(h=>h.rain));return `<div class="chart-panel"><div class="forecast-tag">24-hour precipitation forecast · Open-Meteo</div><svg class="chart" viewBox="0 0 720 150" role="img" aria-label="Hourly precipitation forecast in millimetres"><line x1="35" y1="120" x2="710" y2="120" stroke="#e4e9e6"/><line x1="35" y1="60" x2="710" y2="60" stroke="#edf0eb" stroke-dasharray="3 5"/><text x="2" y="25" fill="#82907b" font-size="9">${fmt(max)} mm</text><text x="8" y="123" fill="#82907b" font-size="9">0</text>${hours.map((h,i)=>`<rect x="${38+i*28}" y="${120-h.rain/max*90}" width="16" height="${Math.max(0,h.rain/max*90)}" fill="#839d75"><title>${esc(time(h.time))}: ${fmt(h.rain)} mm</title></rect>`).join('')}</svg><div class="chart-caption"><span>${time(hours[0].time)}</span><span>${time(hours.at(-1).time)}</span></div></div>`;}
function dashboardView(){const rows=state.overview?.locations??[];return `${nationalStats()}<div class="panel"><div class="panel-header"><div class="panel-title">Reference location comparison</div><small>MODEL OUTPUT · NEVER OBSERVED TOTALS</small></div><div class="table-wrap"><table><thead><tr><th>LOCATION / REGION</th><th>RAIN · NEXT 24H</th><th>RAIN · NEXT 7D</th><th>TEMP</th><th>DISCHARGE</th><th>STATUS</th></tr></thead><tbody>${rows.map(s=>`<tr><td><a href="/flood-risk/${esc(s.location.slug)}">${esc(s.location.name)} ↗</a><span class="subtext">${esc(s.location.province)}</span></td><td class="mono">${fmt(s.weather.ok?s.weather.data.rain_next_24h_mm:null)} mm</td><td class="mono">${fmt(s.weather.ok?s.weather.data.rain_next_7d_mm:null)} mm</td><td class="mono">${fmt(s.weather.ok?s.weather.data.temp_c:null)} °C</td><td class="mono">${fmt(s.flood.ok?s.flood.data.discharge_cms:null)} m³/s</td><td><span class="badge" title="Validated local flood-risk calibration is unavailable">FLOOD RISK NOT ASSESSED</span></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty-state">Comparison evidence is being retrieved.</div>':''}</div><div class="lower-grid"><div class="panel"><div class="panel-header"><div class="panel-title">Hourly forecast</div></div>${chart(state.snapshot)}</div>${locationPanel()}</div>`;}
function sourceCard(row){const e=row.envelope;return `<article class="source-card"><div class="source-top"><span class="source-symbol">T${e.source.tier}</span>${badge(e)}</div><h3>${esc(e.source.name)}</h3><p>${esc(e.source.methodology)}</p><div class="source-meta">FAMILY: ${esc(e.source.family)}<br>TYPE: ${esc(e.source.temporal_kind)}<br>LATENCY: ${e.source.latency_ms} ms<br>RETRIEVED: ${esc(time(e.source.retrieved_at))}<br>UPSTREAM: ${esc(time(e.source.updated_at))}<br>TRACE: ${esc(e.trace_id)}<br>ENDPOINT: ${esc(e.source.endpoint??'Request endpoint not supplied; see provider documentation')}<br>LICENSE: ${esc(e.source.license)}</div>${sourcePreview(e)}${!e.ok?`<p class="offline-text">${esc(e.error.code)} · ${esc(e.error.message)}</p>`:''}<a class="source-link" href="${safeUrl(e.source.url)}" target="_blank" rel="noopener">Visit original source ↗</a></article>`;}
function sourcesView(detail){const rows=detail?(state.sources??[]).filter(r=>r.envelope.source.id===detail):state.sources??[];return `<div class="toolbar"><input id="source-filter" type="search" placeholder="Filter sources…" aria-label="Filter evidence sources"><span class="coordinates">Point feeds sampled at Karachi · catalog feeds retain their own scopes</span></div><div class="source-grid">${rows.map(sourceCard).join('')}</div>${!rows.length?'<div class="empty-state">No source with that identifier is registered.</div>':''}`;}
function opsView(){const rows=state.sources??[];const samples=rows.filter(r=>!r.envelope.cached&&r.envelope.ok).map(r=>r.envelope.source.latency_ms).sort((a,b)=>a-b);const median=samples.length?(samples[Math.floor((samples.length-1)/2)]+samples[Math.floor(samples.length/2)])/2:null;return `<div class="stat-grid">${stat('Registered connectors',fmt(state.sources?.length,0),'sources','Includes unavailable integrations','◇')}${stat('Available responses',fmt(state.sources?.filter(r=>r.envelope.ok).length,0),'sources','Data retrieval availability only','⌁')}${stat('Circuit policy','5','failures','60-second cooldown · single probe','↻')}${stat('Median fresh latency',fmt(median,0),'ms',`${samples.length} successful uncached responses · not historical SLO`,'◫')}</div><div class="toolbar"><a class="button" href="/api/public/v1/readiness">Core readiness probe ↗</a><a class="button" href="/api/public/v1/health">Application health ↗</a><a class="button" href="/settings.connectors">Server configuration ↗</a></div><div class="ops-context">Circuit, quarantine and rate-limit state belong to this server instance. Cross-instance persistence and historical SLO measurement are not configured.</div><form id="quarantine-form" class="operator-form"><h2>Operator connector controls</h2><p>Requires a configured server operator token. Quarantine applies to the instance handling this request and may not affect other Vercel instances.</p><label>Source<select id="operator-source">${rows.map(r=>`<option value="${esc(r.health.id)}">${esc(r.envelope.source.name)}</option>`).join('')}</select></label><label>Operator token<input id="operator-token" type="password" autocomplete="off" required minlength="32"></label><label>Action<select id="operator-action"><option value="true">Quarantine</option><option value="false">Release quarantine</option></select></label><button type="submit" class="button">Apply to this instance</button><div id="operator-result" role="status"></div></form><div class="panel"><div class="panel-header"><div class="panel-title">Connector operations ledger</div><small>REQUEST-SCOPED RESPONSE EVIDENCE</small></div><div class="table-wrap"><table><thead><tr><th>SOURCE</th><th>STATUS</th><th>CIRCUIT</th><th>LATENCY</th><th>DIAGNOSTIC</th></tr></thead><tbody>${(state.sources??[]).map(r=>`<tr><td>${esc(r.envelope.source.name)}</td><td>${badge(r.envelope)}</td><td class="mono">${r.health.quarantined?'QUARANTINED':esc(r.health.circuit)}</td><td class="mono">${r.envelope.source.latency_ms} ms</td><td>${r.envelope.ok?'Schema validation passed':esc(r.envelope.error.code)}<span class="subtext">${r.envelope.ok?'Forecast / observation semantics retained':esc(r.envelope.error.message)}</span></td></tr>`).join('')}</tbody></table></div></div>`;}
function briefHTML(b){return historyNotice(b)+(b.tool_calls?`<details class="brief-ledger"><summary>Consulted tools (${b.tool_calls.length})</summary>${b.tool_calls.map(c=>`<p><code>${esc(c.tool)}</code> · ${esc(c.sources.join(', '))}</p>`).join('')}</details>`:'')+b.sections.map((s,i)=>`<section class="brief-section"><h3><span class="number-label">0${i+1}</span>${esc(s.title)}</h3><p>${esc(s.text)}</p></section>`).join('')+`<div class="integrity-footer"><strong>Uncertainty & missing data notice</strong><p>${b.missing_data?.length?b.missing_data.map(e=>esc(e.source+' · '+e.code+' · '+e.reason)).join('<br>'):'Core point connectors returned data. This does not establish hazard safety; independent rainfall, terrain slope, flood thresholds and impacts remain unverified.'}</p></div><details class="brief-ledger"><summary>Inspect the consulted evidence ledger (${b.evidence?.length??0} sources)</summary><div class="source-grid">${(b.evidence??[]).map(e=>sourceCard({envelope:e})).join('')}</div></details>`;}
async function briefView(force=false){const b=await client.get(`briefings?kind=${state.briefKind}&location=${state.selected}`,force);writeHistory(localStorage,`briefings?kind=${state.briefKind}&location=${state.selected}`,b,realNow());return `<div class="tabbar">${[['national','National strategic'],['regional','Provincial context'],['family','Family & commuter'],['agriculture','Agriculture']].map(([k,v])=>`<button class="${k===state.briefKind?'active':''}" data-brief="${k}">${v}</button>`).join('')}</div><div class="toolbar">${selector()}<button class="button" id="download-brief">↓ Export briefing</button><button class="button" id="scheduled-archive">Daily published archive</button><span class="coordinates">COMPILED ${time(b.generated_at)}</span></div><div class="panel"><div class="panel-header"><div class="panel-title">${esc(b.scope)} · ${esc(state.briefKind)} evidence brief</div><span class="badge neutral">DETERMINISTIC</span></div><div class="query-description">${esc(b.scope)}. Coverage is limited to registered reference points, not all administrative districts.</div>${briefHTML(b)}</div>`;}
function saved(){try{const data=JSON.parse(localStorage.getItem('prism.places.v1')??'[]');return Array.isArray(data)?data.filter(s=>state.locations.some(l=>l.slug===s)):[];}catch{return [];}}
function watchView(){const places=saved();return `<div class="toolbar">${selector()}<button class="button primary" id="save-place">+ Save place</button><a class="button" href="/widget">Open mobile widget ↗</a></div><div class="policy-note">BROWSER-LOCAL WATCHLIST · Email, push and server-side alert delivery are not configured.</div><div class="watch-grid">${places.map(slug=>{const l=state.locations.find(l=>l.slug===slug);return `<article class="saved-card"><span class="badge" title="Validated local flood-risk calibration is unavailable">FLOOD RISK NOT ASSESSED</span><h3 style="margin-top:15px">${esc(l.name)}</h3><p>${esc(l.province)} · ${esc(l.profile)}</p><p class="coordinates">${l.lat.toFixed(4)}° N · ${l.lon.toFixed(4)}° E</p><a class="button" href="/flood-risk/${esc(slug)}">Inspect evidence ↗</a> <button class="button remove-place" data-slug="${esc(slug)}" aria-label="Remove ${esc(l.name)}">Remove</button></article>`;}).join('')}</div>${!places.length?'<div class="panel empty-state"><strong>Start with somewhere that matters.</strong>Choose a reference location above to save it on this device.</div>':''}`;}
function officerView(){return `<div class="chat-layout"><div class="panel"><div class="panel-header"><div class="panel-title"><span>✧</span>PRISM Evidence Officer</div><span class="badge neutral">EVIDENCE MODE</span></div><div class="chat-welcome"><div class="officer-orb">✧</div><h2>From signals to understanding.</h2><p>Select a location and request an evidence briefing.<br>Responses contain verified connector outputs and disclose missing inputs.</p><p class="policy-note">Hosted conversational AI tool calling is not configured. An optional browser-local model can select already verified facts.<br>Questions select context; they do not generate factual claims.</p></div><form class="chat-form" id="officer-form"><textarea id="officer-input" maxlength="2000" required placeholder="What evidence is available for my location?" aria-label="Operational question">${esc(state.query)}</textarea>${selector()}<button class="button" type="button" id="use-location">Use my location</button><button class="button primary" type="submit">Generate evidence brief ↗</button><button class="button" type="button" id="ai-summary">Optional local AI summary</button><p class="policy-note">Local AI selects existing facts with WebLLM/Qwen. Requires WebGPU and an initial model download of hundreds of MB; starts only when you choose the AI button.</p></form><div id="officer-reply" class="chat-reply"></div><div id="local-ai-reply" class="brief-section" role="status"></div></div><div><section class="panel"><div class="panel-header"><div class="panel-title">Consulted evidence context</div></div><div id="officer-evidence">${sourceRows()}</div></section><div class="panel brief-card" style="margin-top:20px"><div class="eyebrow">THE OFFICER'S CONSTITUTION</div><h3>Seven sections.<br>One standard of truth.</h3><p>Executive answer · Current situation · Outlook · Impact · Confidence & evidence · Operational actions · Verifiable sources.</p><p>No invented population exposure. No unsupported evacuation instruction. No synthetic live facts.</p></div></div></div>`;}
function methodologyView(){return `<article class="article"><section><h2>The honesty contract</h2><p>PRISM reports data supplied by registered connectors. If a source fails, the envelope is offline and live data is null. Previous successful data can be retained separately as historical context, never as a live replacement. An unavailable source or unassessed risk must never be read as safe.</p></section><section><h2>An evidence ladder, not a credibility ranking</h2><div class="data-list"><div><h3>01 · Ground observation</h3><p>Instrument-derived measurements such as USGS earthquake catalogs and properly integrated ground air sensors.</p></div><div><h3>02 · Earth observation</h3><p>Satellite and radar products. Geographic coverage and retrieval algorithms matter. CHIRPS blends gauges and satellite inputs.</p></div><div><h3>03 · Models & terrain</h3><p>Open-Meteo weather, CAMS air forecasts and GloFAS modelled discharge. These are not ground observations.</p></div><div><h3>04 · Official reports</h3><p>Human-curated reports and agency advisories. Reports can provide authoritative context without numeric sensor measurements.</p></div></div></section><section><h2>Consensus requires comparable, independent evidence</h2><p>Readings must share a parameter, unit, observation or forecast kind, and time window. Stale, unavailable and incompatible readings are excluded. A shared upstream model family counts once, even when accessed through multiple providers. Radar tiles are never converted into rainfall without a validated calibration.</p><div class="formula">M = median(comparable, fresh readings)<br>Agreement: |reading − M| ≤ absolute tolerance + 0.35 × |M|<br>HIGH: ≥ 2 independent agreeing families and ≥ 66% family coverage<br>No comparable observations: INSUFFICIENT</div><p>This heuristic is an agreement indicator, not a statistically calibrated probability or an official hazard designation.</p></section><section><h2>Risk must earn its number</h2><p>The supplied blueprint contains conflicting mountainous and arid weights and circuit thresholds. PRISM adopts five failures for the circuit breaker and leaves hazard scores unassessed. Urban drainage slope, local return-period thresholds, thermal anomalies and population buffers cannot be fabricated. Profile archetypes describe context; they do not validate an operational prediction.</p></section><section><h2>Geographic coverage</h2><p>The registry includes 160 district records from OCHA/WFP COD-AB v01, valid from September 2022 and reviewed in September 2024. It is a dated humanitarian reference, not a certification of current legal boundaries. Point forecasts are available on demand for every listed district centre; the national comparison samples the original 12 city coordinates. Map markers are point references. GPS requests do not infer district membership. A rectangular seismic query can include neighbouring countries.</p></section><section><h2>Freshness & time semantics</h2><p>All server calculations use UTC. The interface displays Pakistan Standard Time. Forecast valid time, source publication time and retrieval time are different fields. A provider that does not publish an issuance timestamp is labelled accordingly. No timestamp is invented.</p></section><section><h2>Current upstream changes</h2><p><a href="https://www.rainviewer.com/api/transition-faq.html" target="_blank" rel="noopener">RainViewer's transition notice ↗</a> states that public future nowcast frames were discontinued in January 2026. PRISM exposes available past frames and does not promise a two-hour public forecast.</p><p><a href="https://open-meteo.com/en/docs/flood-api" target="_blank" rel="noopener">Open-Meteo Flood documentation ↗</a> describes model discharge at the largest river within 5 km. This is not a gauging station reading, and calibrated flood return periods are unavailable here.</p></section></article>`;}
function informationView(page){const content={privacy:['Privacy','PRISM has no analytics trackers in this edition. Saved places and cached briefings stay in browser storage. Climate queries send reference coordinates to public providers through the server. If you explicitly use device location, the browser requests your permission and sends coordinates to PRISM and its weather, discharge, air and elevation providers. Device-coordinate evidence is not persisted in PRISM browser history. Hosting/provider access logs may contain request coordinates. Basemap tiles and fonts are loaded from OpenStreetMap and Google; those providers receive standard browser requests. Leaflet loads from jsDelivr. Optional local AI downloads a model/runtime from CDN and model hosts only when selected; evidence selection runs on the device.','No cloud profile or notification delivery is configured. Remove device preferences by clearing site storage.'],terms:['Terms & public data disclaimer','PRISM is an independent experimental information platform. It is not PMD, NDMA, or an official emergency warning authority. Source availability and forecast performance vary.','Operational risk models have not been locally calibrated. Do not rely on the platform alone for evacuation, travel, agricultural, or civil defense decisions. Consult official guidance. Provider usage and attribution terms apply.'],changelog:['Release 0.4 · District forecast workspace','Detailed district forecasts now include 168 hourly slots, feels-like temperature, humidity, wind and gusts, precipitation probability, coverage receipts, three charts, CSV and JSON reports, and print layouts. Updated existing platform: scoped offline widget history, device-coordinate evidence, route metadata, API documentation, crawler files, per-reading source inspection, missing-data briefing footers, guarded instance-local quarantine and visible half-open recovery. Foundation: resilient server-side connectors, provenance envelopes, reference-location atlas, comparative forecast dashboard, source-health ledger, deterministic evidence officer, exportable briefings, local watchlist and mobile widget.','Honesty corrections: no fabricated 160-district coverage, no invented flood return periods, no public radar nowcast promise, no uncalibrated risk scores.'],contact:['Operational contact','An operational support channel has not been configured. This page cannot submit messages or contact emergency services.','For official disaster guidance, visit NDMA at ndma.gov.pk or the Pakistan Meteorological Department at pmd.gov.pk.']};const c=content[page];return `<article class="article"><section><h2>${c[0]}</h2><p>${c[1]}</p><p>${c[2]}</p></section></article>`;}
function unavailableView(page){if(page==='auth'||page==='reset-password')return `<div class="auth-box"><h2>Cloud sign-in is not configured.</h2><p>No identity provider or hosted PostgreSQL project has been connected. PRISM does not display a login flow that cannot authenticate you.</p><p>You can explore evidence and save places locally now. Cloud accounts, magic links, password recovery, email alerts and role-based workflows require a configured provider.</p><a class="button primary" href="/watch">Use the local watchlist ↗</a></div>`;return `<div class="panel empty-state"><strong>${page.startsWith('river')?'River basin registry unavailable':'Cloud service not configured'}</strong>${page.startsWith('river')?'Point model discharge is visible in location snapshots. Verified basin boundaries, station coordinates and calibrated thresholds have not been supplied.':'Cloud profiles, user roles, connector secrets and developer keys require a configured authenticated backend. Keys cannot be stored through this public interface.'}<br><br><a class="button" href="/sources">Inspect available sources ↗</a></div>`;}
async function detailView(slug){state.selected=slug;state.snapshot=await client.get('districts/'+slug);const s=state.snapshot;return `<div class="toolbar"><span class="coordinates">${s.location.lat.toFixed(4)}° N · ${s.location.lon.toFixed(4)}° E</span><span class="badge">RISK NOT CALIBRATED</span><a class="button primary" href="/forecast?location=${esc(slug)}">Full seven-day forecast ↗</a><button class="button" id="save-place">⌖ Save place</button></div><div class="detail-grid"><section class="panel"><div class="panel-header"><div class="panel-title">${esc(s.location.name)} · Forecast context</div><span class="badge neutral">MODEL OUTPUT</span></div>${chart(s)}<div class="query-description">${esc(s.risk.reason)}</div>${sourceRows()}</section>${locationPanel()}</div><section class="panel" style="margin-top:22px"><div class="panel-header"><div class="panel-title">Satellite rainfall archive</div><button id="load-chirps" class="button">Retrieve CHIRPS archive</button></div><p>Thirty calendar days of area-mean rainfall over a 0.05° square, ending on the latest usable archive day returned. Publication lag is shown explicitly.</p><div id="chirps-archive" aria-live="polite">Archive runs only when requested. Missing days remain unavailable.</div></section><section class="panel" style="margin-top:22px"><div class="panel-header"><div class="panel-title">People & nearby facilities</div><button id="load-community" class="button">Retrieve community context</button></div><p>WorldPop 2025 population estimate for a query square; OpenStreetMap school, hospital, clinic and fire-station nodes and ways in the same query square. These are geographic context, not flood impacts or safe destinations.</p><div id="community-context" aria-live="polite">Retrieve source-backed geographic context for this district reference point.</div></section><div class="panel" style="margin-top:22px"><div class="panel-header"><div class="panel-title">Modelled daily river discharge</div></div>${s.flood.ok?`<div class="table-wrap"><table><thead><tr><th>VALID DATE</th><th>DISCHARGE</th><th>CLASSIFICATION</th></tr></thead><tbody>${s.flood.data.days.map(d=>`<tr><td class="mono">${esc(d.time)}</td><td class="mono">${fmt(d.discharge)} m³/s</td><td>Modelled · not a station observation</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>DATA SOURCE OFFLINE</strong>${esc(s.flood.error.message)}</div>`}<div class="query-description">Return period unavailable. A single-point elevation cannot establish terrain slope or flood inundation.</div></div>`;}
function setHeading(view){const d=descriptions[view];if(d){$('#page-title').innerHTML=d[0];$('#page-description').innerHTML=d[1];}else{$('#page-title').textContent=view.startsWith('flood-risk')?(state.locations.find(l=>l.slug===view.split('/')[1])?.name??'Location evidence'):view.split('/')[0].replaceAll('-',' ').replaceAll('.',' ');$('#page-description').textContent='A transparent view of the platform and its current capabilities.';}$('#breadcrumb').textContent=view==='overview'?'National overview':view.replaceAll('/',' / ').replaceAll('-',' ');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===view));}
async function render(force=false){const ownEpoch=++renderEpoch,selectionEpoch=pointEpoch;const raw=location.pathname.replace(/^\/+|\/+$/g,'');const view=raw||'overview';state.view=view;disposeMap();setHeading(view);const content=$('#content');if(!(view==='alerts'&&force&&content.querySelector('.hazard-desk')))content.innerHTML='<div class="loading-state">Retrieving source-backed evidence…</div>';content.setAttribute('aria-busy','true');try{let html;
 if(['overview','dashboard','map','officer'].includes(view)){const needsOverview=['overview','dashboard'].includes(view);if(view==='overview'||view==='dashboard'){content.innerHTML=view==='overview'?overviewView():dashboardView();observeMap();bindInteractions();}const snapshotPromise=client.get(selectedSnapshotPath(),force).then(s=>{if(ownEpoch===renderEpoch&&selectionEpoch===pointEpoch){state.snapshot=s;if(view==='overview'||view==='dashboard'){content.innerHTML=view==='overview'?overviewView():dashboardView();observeMap();bindInteractions();}}return s;});const [s,o]=await Promise.all([snapshotPromise,needsOverview?client.get('districts',force):Promise.resolve(state.overview)]);if(ownEpoch!==renderEpoch)return;if(selectionEpoch===pointEpoch)state.snapshot=s;if(o)state.overview=o;if(view==='overview')html=overviewView();else if(view==='dashboard')html=dashboardView();else if(view==='officer')html=officerView();else html=`<div class="map-stats"><span>160 published district centres · 2 city aliases</span><span>NASA satellite evidence · past radar</span><a class="button" href="/dashboard">Compare forecasts ↗</a></div><section class="panel">${mapHTML(true)}</section><div class="lower-grid" style="margin-top:22px">${locationPanel()}${floodOutlook()}</div>`;
 }else if(view==='forecast'){const slug=state.selected;const forecast=await client.get('weather-detail?location='+slug,force);if(ownEpoch!==renderEpoch||slug!==state.selected)return;state.forecast=forecast;history.replaceState(null,'','/forecast?location='+encodeURIComponent(slug));html=forecastView();}else if(view==='briefings')html=await briefView(force);else if(view==='watch')html=watchView();else if(view==='methodology')html=methodologyView();else if(view==='sources'||view.startsWith('sources/')||view==='ops'){state.sources=await client.get('sources',force);html=view==='ops'?opsView():sourcesView(view.split('/')[1]);}
 else if(view.startsWith('flood-risk/'))html=await detailView(view.split('/')[1]);else if(['privacy','terms','changelog','contact'].includes(view))html=informationView(view);else if(view==='api')html=apiView();else if(view==='widget'){state.snapshot=await client.get('districts/'+state.selected,force);const b=await client.get(`briefings?kind=family&location=${state.selected}`,force);html=widgetPlaces()+`<div class="widget-shell">${locationPanel()}<div class="panel" style="margin-top:20px">${briefHTML(b)}</div><p class="policy-note">Pin this page using your browser's Add to Home Screen option. Last retrieval ${time(b.generated_at)}.</p></div>`;}
 else if(view==='alerts')html=await alertsView(force);else if(view==='settings.connectors')html=await connectorSettingsView();else if(view==='settings.developer')html=apiView();else if(view==='auth'||view==='reset-password')html=workspaceView();else if([].includes(view)||view.startsWith('river/'))html=unavailableView(view);else html='<div class="empty-state"><strong>Page not found.</strong><a href="/">Return to the observatory ↗</a></div>';
 if(ownEpoch!==renderEpoch)return;content.innerHTML=html;content.setAttribute('aria-busy','false');observeMap();bindInteractions();
 }catch(error){if(ownEpoch!==renderEpoch)return;content.setAttribute('aria-busy','false');content.innerHTML=`<div class="error-box"><strong>Data Unavailable</strong><br>${esc(error.message)}. No replacement values have been generated.<br><br><button class="button" id="retry">Retry evidence request</button></div>`;$('#retry')?.addEventListener('click',()=>render(true));}
}
async function selectLocation(slug){if(state.view.startsWith('flood-risk/')){try{localStorage.setItem('prism.selected.v1',slug);}catch{}location.assign('/flood-risk/'+encodeURIComponent(slug));return;}if(state.view==='forecast'){state.selected=slug;state.point=null;try{localStorage.setItem('prism.selected.v1',slug);}catch{}await render();return;}const epoch=++pointEpoch;state.selected=slug;state.point=null;try{localStorage.setItem('prism.selected.v1',slug);}catch{}try{const snapshot=await client.get('districts/'+slug);if(epoch!==pointEpoch)return;state.snapshot=snapshot;if(atlas?.map){atlas.mark([snapshot.location.lat,snapshot.location.lon]);updatePointPanels();}else await render();}catch(e){toast(e.message);}}
function bindLocationActions(){const select=$('#location-select');select?.addEventListener('change',()=>selectLocation(select.value));$('#save-place')?.addEventListener('click',()=>{if(state.point){toast('Choose a named place to save it. Custom-coordinate watchlists are not yet supported.');return;}const places=saved();if(!places.includes(state.selected))places.push(state.selected);try{localStorage.setItem('prism.places.v1',JSON.stringify(places));toast('Place saved on this device.');if(state.view==='watch')render();}catch{toast('Browser storage unavailable.');}});}
function bindInteractions(){bindForecastActions();loadSatellitePoint();$('#scheduled-archive')?.addEventListener('click',loadDailyArchive);$('#place-search')?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();const q=event.target.value.toLowerCase(),match=state.locations.find(l=>(l.name+' '+l.province).toLowerCase().includes(q));if(match)selectLocation(match.slug);}});$('#place-search')?.addEventListener('input',event=>{const q=event.target.value.toLowerCase();const select=$('#location-select');for(const option of select.options)option.hidden=!option.text.toLowerCase().includes(q);});$('#load-chirps')?.addEventListener('click',loadChirps);$('#load-community')?.addEventListener('click',loadCommunity);$('#export-places')?.addEventListener('click',exportPlaces);$('#import-places')?.addEventListener('change',importPlaces);$('#clear-places')?.addEventListener('click',()=>{localStorage.removeItem('prism.places.v1');toast('Watchlist cleared on this device.');});$('#ai-summary')?.addEventListener('click',localAISummary);$('#officer-input')?.addEventListener('input',e=>{state.query=e.target.value;});$('#quarantine-form')?.addEventListener('submit',async e=>{e.preventDefault();const token=$('#operator-token').value;$('#operator-token').value='';const button=$('button[type="submit"]',e.target);button.disabled=true;try{const r=await fetch('/api/ops/quarantine',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({source:$('#operator-source').value,quarantined:$('#operator-action').value==='true'})});const result=await r.json();$('#operator-result').textContent=r.ok?`${result.source}: ${result.quarantined?'quarantined':'released'} · ${result.scope}`:`HTTP ${r.status} · ${result.message??result.error}`;}catch{$('#operator-result').textContent='Operation could not be confirmed. Inspect source health before retrying.';}finally{button.disabled=false;}});document.querySelectorAll('[data-widget-place]').forEach(b=>b.onclick=()=>selectLocation(b.dataset.widgetPlace));$('#use-location')?.addEventListener('click',deviceAssessment);const select=$('#location-select');select?.addEventListener('change',()=>selectLocation(select.value));$('#save-place')?.addEventListener('click',()=>{if(state.point){toast('Choose a registered reference place to save it.');return;}const places=saved();if(!places.includes(state.selected))places.push(state.selected);try{localStorage.setItem('prism.places.v1',JSON.stringify(places));toast('Place saved on this device.');if(state.view==='watch')render();}catch{toast('Browser storage unavailable.');}});document.querySelectorAll('.remove-place').forEach(b=>b.onclick=()=>{localStorage.setItem('prism.places.v1',JSON.stringify(saved().filter(s=>s!==b.dataset.slug)));render();});document.querySelectorAll('[data-brief]').forEach(b=>b.onclick=()=>{state.briefKind=b.dataset.brief;render();});$('#download-brief')?.addEventListener('click',async()=>{const brief=await client.get(`briefings?kind=${state.briefKind}&location=${state.selected}`);const blob=new Blob([JSON.stringify(brief,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`prism-${state.selected}-${state.briefKind}-evidence.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});$('#source-filter')?.addEventListener('input',event=>{const q=event.target.value.toLowerCase();document.querySelectorAll('.source-card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(q));});$('#radar-layer')?.addEventListener('click',async()=>{try{const r=await client.get('radar');toast(r.ok?`${r.data.frames.length} past radar frames available. Pakistan coverage not verified; public nowcast discontinued.`:`Radar offline: ${r.error.code}`);}catch(e){toast(e.message);}});$('#officer-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type="submit"]',e.target);button.disabled=true;$('#officer-reply').innerHTML='<div class="loading-state">Compiling the evidence ledger…</div>';try{const streamed=[];const b=await client.officer($('#officer-input').value,state.selected,event=>{if(event.type==='status'&&!streamed.length)$('#officer-reply').textContent=event.text;if(event.type==='section'){streamed.push(event.section);$('#officer-reply').innerHTML=streamed.map((section,i)=>`<section class="brief-section"><h3><span class="number-label">0${i+1}</span>${esc(section.title)}</h3><p>${esc(section.text)}</p></section>`).join('');}});$('#officer-reply').innerHTML=briefHTML(b);const ledger=$('#officer-evidence');if(ledger)ledger.innerHTML=`<div class="query-description">Consulted for ${esc(b.location.name)}</div>`+(b.evidence??[]).map(e=>`<a class="list-row" href="/sources/${esc(e.source.id)}"><div><h3>${esc(e.source.name)} · Tier ${e.source.tier}</h3><small>${e.source.latency_ms} ms · ${esc(time(e.source.retrieved_at))}</small></div>${badge(e)}</a>`).join('');}catch(e){$('#officer-reply').innerHTML=`<div class="error-box">${esc(e.message)}</div>`;}finally{button.disabled=false;}});}
$('#refresh').addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;client.cache.clear();await render(true);button.disabled=false;});$('.mobile-menu').addEventListener('click',e=>{const open=$('.sidebar').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});
function updateClock(){const now=serverClock.now();if(now===null){$('#clock').textContent='SERVER TIME UNAVAILABLE';$('#date').textContent='Date awaiting server verification';return;}const date=new Date(now);$('#clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)+' PKT';$('#clock').title='Synchronized with PRISM server time; device clock is not used';$('#date').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(date).toUpperCase();}
async function synchronizeClock(){try{await withTimeout(10000, async signal => {const response=await fetch('/api/public/v1/time',{cache:'no-store',signal});if(!response.ok)throw new Error('Clock unavailable');const value=await response.json();serverClock.synchronize(value.server_time);updateClock();});}catch{if(serverClock.now()===null)updateClock();else $('#clock').title='Last server synchronization retained; retrying shortly';}}
updateClock();await synchronizeClock();setInterval(updateClock,10000);setInterval(synchronizeClock,300000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){synchronizeClock();if(state.view==='alerts'&&!refreshing){refreshing=true;render(true).finally(()=>refreshing=false);}}});
try{const r=await client.get('locations');state.locations=r.locations;const requested=new URLSearchParams(location.search).get('location');try{const selected=localStorage.getItem('prism.selected.v1');if(state.locations.some(l=>l.slug===selected))state.selected=selected;}catch{}if(state.locations.some(l=>l.slug===requested))state.selected=requested;await render();}catch(error){$('#content').innerHTML=`<div class="error-box">${esc(error.message)}. Location registry unavailable.</div>`;}
setInterval(async()=>{if(document.hidden||refreshing)return;refreshing=true;try{if(['overview','map','dashboard','officer'].includes(state.view)){state.snapshot=await client.get(selectedSnapshotPath(),true);updatePointPanels();if(['overview','dashboard'].includes(state.view)){state.overview=await client.get('districts',true);const stats=$('.stat-grid');if(stats)stats.outerHTML=nationalStats();if(state.view==='dashboard')await render();}if(atlas){atlas.imagery=await client.get('imagery',true);atlas.radar=await client.get('radar',true);await atlas.update();}}else if(state.view==='widget'||state.view==='forecast'||state.view==='alerts')await render(true);}catch(e){toast('Automatic refresh failed: '+e.message);}finally{refreshing=false;}},300000);



if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function widgetPlaces(){const places=saved();return `<div class="widget-places" aria-label="Saved widget places">${places.map(slug=>`<button class="button ${slug===state.selected?'primary':''}" data-widget-place="${esc(slug)}">${esc(state.locations.find(l=>l.slug===slug).name)}</button>`).join('')}</div>`;}
function apiView(){return `<article class="article"><section><h2>Evidence you can build on.</h2><p>The same provenance envelopes power the public interface and JSON APIs. Forecasts remain model outputs; an offline envelope carries null data and an explicit error. No developer key is required in this pilot. Requests are limited on a best-effort, per-instance basis.</p></section><section><h2>Public endpoints</h2><p><a class="button" href="/openapi.json">OpenAPI 3.1 specification ↗</a> <a class="button" href="/forecast">Inspect a detailed forecast ↗</a></p><div class="table-wrap"><table><thead><tr><th>METHOD</th><th>PATH</th><th>PURPOSE</th></tr></thead><tbody>${[['GET','/api/public/v1/readiness','Four core point feeds; 503 when degraded, no certification claim'],['GET','/api/public/v1/weather-detail?location=karachi','168 hourly slots, rolling daily windows, missing-value coverage'],['GET','/api/public/v1/locations','District centres and city references'],['GET','/api/public/v1/district-registry','160 OCHA/WFP records and dated provenance'],['GET','/api/public/v1/gdacs','Pakistan-attributed GDACS reports'],['GET','/api/public/v1/chirps?location=karachi','Polled satellite rainfall archive'],['GET','/api/public/v1/scheduled-briefings','Published historical daily archive'],['GET','/api/public/v1/districts/karachi','Point weather, discharge, air and elevation'],['GET','/api/public/v1/point?lat=24.8607&lon=67.0011','Coordinate evidence; no district boundary inference'],['GET','/api/public/v1/sources','Envelope ledger and circuit health'],['GET','/api/public/v1/briefings?kind=family&location=karachi','Structured seven-section evidence brief'],['GET','/api/public/v1/earthquakes','Regional USGS event catalog'],['GET','/api/public/v1/active-fires','Public NASA VIIRS thermal detections'],['POST','/api/officer','Deterministic location and audience routing'],['POST','/mcp','JSON-RPC tools/list and tools/call']].map(([m,p,d])=>`<tr><td>${m}</td><td class="mono">${m==='GET'?`<a href="${esc(p)}">${esc(p)} ↗</a>`:esc(p)}</td><td>${d}</td></tr>`).join('')}</tbody></table></div></section><section><h2>Interpret the contract</h2><p><code>ok: false</code> means the current reading is unavailable. <code>data: null</code> must not be replaced by zero. <code>last_success</code>, when supplied, is historical context. <code>source.updated_at</code> is source/valid time; <code>source.retrieved_at</code> is retrieval time. Tier and family explain evidence type and independence.</p><p>The district registry contains 160 dated OCHA/WFP records; national comparisons sample 12 city reference points. District-centre forecasts are point readings, not area aggregates. Calibrated risk scores and return periods remain unavailable. Cross-origin API access is not configured; use server-to-server requests or the same origin.</p></section></article>`;}
async function deviceAssessment(){const button=$('#use-location');if(!navigator.geolocation){toast('Device geolocation is unavailable in this browser.');return;}button.disabled=true;$('#officer-reply').innerHTML='<div class="loading-state">Waiting for device location permission…</div>';try{const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{timeout:15000,maximumAge:0,enableHighAccuracy:false}));const {latitude:lat,longitude:lon,accuracy}=position.coords;const point=await client.get(`point?lat=${lat}&lon=${lon}`,true);$('#officer-reply').innerHTML=`<div class="brief-section"><h3>Device coordinate assessment</h3><p>${fmt(lat,4)}° N · ${fmt(lon,4)}° E · device accuracy ±${fmt(accuracy,0)} m. These are point model outputs within the monitoring rectangle; district boundaries, nearby river attribution and hazard safety are unverified.</p></div><div class="data-list">${[point.weather,point.flood,point.air,point.elevation].map(e=>sourceCard({envelope:e})).join('')}</div><div class="integrity-footer"><strong>Hazard status: UNASSESSED</strong><p>Device coordinates are used for this request. They are not saved in your watchlist or sent to an AI provider.</p></div>`;}catch(error){$('#officer-reply').innerHTML=`<div class="error-box">${esc(error.code===1?'Location permission was denied. Select a place instead.':error.message??'Location could not be retrieved.')}</div>`;}finally{button.disabled=false;}}

async function localAISummary(){const button=$('#ai-summary'),target=$('#local-ai-reply');button.disabled=true;target.textContent='Retrieving verified facts…';let facts;try{const question=$('#officer-input').value;const matches=state.locations.filter(l=>new RegExp('\\b'+l.name+'\\b','i').test(question));if(matches.length>1)throw new Error('Ask about one registered location at a time.');const snapshot=await client.get(matches.length?'districts/'+matches[0].slug:selectedSnapshotPath(),true);let imagery;try{imagery=await client.get('imagery');}catch{}facts=evidenceFacts(snapshot,imagery,null);const selected=await freeAI.summarize(facts,question,text=>target.textContent=text);target.replaceChildren();const heading=document.createElement('h3');heading.textContent='AI-selected existing evidence · '+snapshot.location.name;target.append(heading);for(const text of selected){const p=document.createElement('p');p.textContent=text;target.append(p);}const note=document.createElement('p');note.textContent='This is local evidence selection, not a conversational tool-calling officer or a hazard warning.';target.append(note);}catch(error){target.replaceChildren();const notice=document.createElement('p');notice.textContent='Local AI unavailable: '+error.message;target.append(notice);if(facts){const heading=document.createElement('h3');heading.textContent='Verified evidence brief';target.append(heading);for(const fact of facts){const p=document.createElement('p');p.textContent=fact;target.append(p);}}}finally{button.disabled=false;}}

async function alertsView(force=false){
 const slug=state.selected;
 const retrieve=async path=>{try{return await client.get(path,force);}catch(error){return {request_error:error.message};}};
 const [n,g,q,f,s]=await Promise.all(['advisories','gdacs','earthquakes','active-fires','districts/'+slug].map(retrieve));
 if(s.location&&slug===state.selected)state.snapshot=s;
 return hazardDesk({n,g,q,f,s,location:state.locations.find(l=>l.slug===slug),helpers:{esc,fmt,time,safeUrl,badge,provenance,selector},checkedAt:serverClock.now()});
}
async function connectorSettingsView(){const c=await client.get('capabilities');return `<article class="article"><section><h2>Server connector configuration</h2><p>Credentials belong in your hosting provider's server environment. This public interface shows configuration presence without exposing secret values. NASA FIRMS public downloads, WorldPop small-area calculations and OpenStreetMap facilities do not require a PRISM API key.</p><div class="table-wrap"><table><thead><tr><th>ENVIRONMENT NAME</th><th>STATUS</th><th>PURPOSE</th></tr></thead><tbody>${c.configuration.map(r=>`<tr><td class="mono">${esc(r.name)}</td><td>${r.configured?'CONFIGURED':'REQUIRED'}</td><td>${esc(r.purpose)}</td></tr>`).join('')}</tbody></table></div><p>Request your own <a href="https://explore.openaq.org/register" target="_blank" rel="noopener">OpenAQ account/API key ↗</a> and <a href="https://apidoc.reliefweb.int/parameters#appname" target="_blank" rel="noopener">approved ReliefWeb application name ↗</a>. Store them as server environment variables in Vercel, then redeploy. Provider registration and approval must be completed by the account owner.</p></section><section><h2>Scientific completion gates</h2><p>160 district centres have published provenance. A point forecast does not establish district-wide hazard. WorldPop query-area estimates and OSM nearby facilities are connected. Flood-exposed populations, gauge return periods, calibrated drainage and GLOF models, and school/road closures still require independently verified inputs.</p><p><a class="button" href="/sources">Inspect feed health ↗</a> <a class="button" href="/ops">Operator controls ↗</a></p></section></article>`;}
function workspaceView(){return `<article class="article"><section><h2>Your device workspace</h2><p>PRISM's watchlist is available immediately on this device. No sign-in is needed. Cloud accounts and password recovery are not enabled; the controls below operate on your local saved places.</p><a class="button primary" href="/watch">Open my places ↗</a></section><section><h2>Portable saved places</h2><p>Export your named places as JSON, then import the file on another device. Imports accept only registered place identifiers and contain no device coordinates or cached telemetry.</p><button class="button" id="export-places">Export places</button><label class="button">Import places <input type="file" id="import-places" accept="application/json,.json"></label><button class="button" id="clear-places">Clear saved places</button></section></article>`;}
function exportPlaces(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({format:'prism-watchlist-v1',places:saved()},null,2)],{type:'application/json'}));a.download='prism-places.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function importPlaces(event){try{const file=event.target.files[0];if(!file||file.size>20000)throw new Error('Choose a watchlist JSON file below 20 KB.');const value=JSON.parse(await file.text());if(value.format!=='prism-watchlist-v1'||!Array.isArray(value.places)||value.places.length>162||value.places.some(slug=>typeof slug!=='string'||!state.locations.some(l=>l.slug===slug)))throw new Error('Watchlist contains invalid or unregistered places.');localStorage.setItem('prism.places.v1',JSON.stringify([...new Set(value.places)]));toast('Saved places imported on this device.');}catch(e){toast(e.message);}finally{event.target.value='';}}
async function loadChirps(){const target=$('#chirps-archive'),button=$('#load-chirps'),slug=state.selected;button.disabled=true;target.textContent='Submitting and polling the ClimateSERV archive job…';try{const e=await client.get('chirps?location='+slug,true);if(state.selected!==slug)return;if(!e.ok){target.innerHTML=`<div class="${e.error.code==='JOB_PENDING'?'policy-note':'error-box'}">${e.error.code==='JOB_PENDING'?'PROCESSING':'DATA SOURCE OFFLINE'} · ${esc(e.error.code)} · ${esc(e.error.message)}</div>${provenance(e)}`;return;}target.innerHTML=`<p>${esc(e.data.window.start)}–${esc(e.data.window.end)} UTC · archive lag ${e.data.lag_days} days · ${e.data.available_days}/30 usable days. ${e.data.total_30d_mm===null?'Thirty-day total unavailable; partial available-day sum: '+fmt(e.data.available_sum_mm):'Thirty-day cumulative rainfall: '+fmt(e.data.total_30d_mm)} mm.</p><div class="table-wrap"><table><thead><tr><th>DAY (UTC)</th><th>AREA-MEAN RAINFALL</th></tr></thead><tbody>${e.data.days.map(d=>`<tr><td>${esc(d.date)}</td><td>${d.rain_mm===null?'MISSING':fmt(d.rain_mm)+' mm'}</td></tr>`).join('')}</tbody></table></div><p>${esc(e.data.note)}</p>${provenance(e)}`;}catch(e){target.textContent='Archive request failed: '+e.message;}finally{button.disabled=false;}}

async function loadDailyArchive(){const button=$('#scheduled-archive');button.disabled=true;try{const e=await client.get('scheduled-briefings',true);if(!e.ok){toast('Daily archive unavailable: '+e.error.code+' · '+e.error.message);return;}const b=e.data.briefings.find(b=>b.kind===state.briefKind&&(b.location.slug===state.selected||state.briefKind==='national'));if(!b){toast('No published daily archive for this location/track. Use the live on-demand brief.');return;}const panel=$('.panel');panel.innerHTML=`<div class="history-banner"><strong>DAILY ARCHIVE · ${e.data.age_minutes} min old</strong><span>Generated ${esc(time(e.data.generated_at))}. Historical evidence; provider timestamps remain unchanged.</span></div>${briefHTML(b)}${provenance(e)}`;}catch(e){toast(e.message);}finally{button.disabled=false;}}

function forecastView(){const place=state.locations.find(l=>l.slug===state.selected);return `<div class="toolbar forecast-toolbar">${selector()}<button class="button" id="save-place">+ Save place</button><button class="button" id="forecast-csv" ${state.forecast.ok?'':'disabled'}>↓ Hourly CSV</button><button class="button" id="forecast-json">↓ Evidence JSON</button><button class="button" id="forecast-print">Print report</button><a class="button" href="/flood-risk/${esc(place.slug)}">River & satellite evidence ↗</a></div>${detailedForecastHTML(state.forecast,place)}`;}
function bindForecastActions(){document.querySelectorAll('[data-forecast-variable]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-forecast-variable]').forEach(b=>{b.classList.toggle('primary',b===button);b.setAttribute('aria-pressed',String(b===button));});$('#forecast-chart').innerHTML=forecastChart(state.forecast,button.dataset.forecastVariable);}));const place=state.locations.find(l=>l.slug===state.selected);const download=(body,type,extension)=>{const url=URL.createObjectURL(new Blob([body],{type}));const link=document.createElement('a');link.href=url;link.download=`prism-${state.selected}-forecast.${extension}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#forecast-csv')?.addEventListener('click',()=>download(forecastCSV(state.forecast,place),'text/csv;charset=utf-8','csv'));$('#forecast-json')?.addEventListener('click',()=>download(JSON.stringify({location:place,envelope:state.forecast},null,2),'application/json','json'));$('#forecast-print')?.addEventListener('click',()=>window.print());}

async function loadCommunity(){const target=$('#community-context'),button=$('#load-community'),slug=state.selected;button.disabled=true;target.textContent='Retrieving WorldPop population and mapped facilities…';try{const c=await client.get('community-context?location='+slug,true);if(state.selected!==slug)return;target.innerHTML=communityHTML(c);}catch(e){target.textContent='Community context request failed: '+e.message;}finally{button.disabled=false;}}
function communityHTML(c){const p=c.population,i=c.infrastructure;return `<div class="source-grid">${[p,i].map(e=>sourceCard({envelope:e})).join('')}</div>${p.ok?`<p><strong>${fmt(p.data.total_population,0)} people · ${p.data.data_year} model estimate</strong> in ${fmt(p.data.area_km2,3)} km². Dataset: ${esc(p.data.data_source)}. Query square centred at ${fmt(c.location.lat,4)}° N, ${fmt(c.location.lon,4)}° E. This is not a district total or number exposed to flooding.</p>`:''}${i.ok?`<p>${i.data.features.length} mapped facilities matched the query-square map lookup. Verify operating status directly.</p><div class="data-list">${i.data.features.map(f=>`<a href="${safeUrl(f.url)}" class="list-row" target="_blank" rel="noopener"><div><h3>${esc(f.name??'Unnamed mapped facility')}</h3><small>${esc(f.kind)} · ${fmt(f.lat,5)}, ${fmt(f.lon,5)} · ${esc(f.coordinate_kind)}</small></div><span>Inspect OSM ↗</span></a>`).join('')}</div>`:''}<p>${esc(c.note)}</p>`;}

function sourcePreview(e){if(!e.ok)return "";const d=e.data;if(e.source.id==="worldpop")return `<p><strong>${fmt(d.total_population,0)} people · ${d.data_year} estimate</strong><br>${fmt(d.area_km2,3)} km² query square. Not district population or flood exposure.</p>`;if(e.source.id==="osm")return `<p><strong>${d.features.length} mapped facilities</strong><br>Query-square nodes and ways. Operating status unverified.</p>`;if(e.source.id==="firms")return `<p><strong>${d.detections.length} satellite thermal detections</strong><br>Actual observation times retained. <a href="/alerts">Inspect thermal evidence ↗</a></p>`;return "";}
